sys_script_client.script:
function onSubmit() {
    var userId = g_form.getValue('user');
    var scheduleId = g_form.getValue('schedule');

    if (!userId) {
        g_form.showFieldMsg('user', 'Error: User is required.', 'error');
        return false;
    }

    if (!scheduleId) {
        g_form.showFieldMsg('schedule', 'Error: Schedule is required.', 'error');
        return false;
    }

    // STRY 7 — Check if user is already enrolled in this specific schedule
    var gaDuplicate = new GlideAjax('x_1960572_training.TrainingHubUtils');
    gaDuplicate.addParam('sysparm_name', 'checkDuplicateEnrollment');
    gaDuplicate.addParam('sysparm_user', userId);
    gaDuplicate.addParam('sysparm_schedule', scheduleId);
    gaDuplicate.getXMLAnswer(function(answerDuplicate) {
        if (answerDuplicate === 'true') {
            g_form.showFieldMsg('schedule', 'Error: This user is already enrolled in this schedule!', 'error');
            return;
        }

        // STRY 8 — Check if user has reached the 3-enrollment limit for this course
        var gaLimit = new GlideAjax('x_1960572_training.TrainingHubUtils');
        gaLimit.addParam('sysparm_name', 'checkEnrollmentLimit');
        gaLimit.addParam('sysparm_user', userId);
        gaLimit.addParam('sysparm_schedule', scheduleId);
        gaLimit.getXMLAnswer(function(answerLimit) {
            if (answerLimit === 'true') {
                g_form.showFieldMsg('schedule', 'Error: This user has already been enrolled 3 times in this course!', 'error');
                return;
            }
            gsftSubmit(null, g_form.getFormElement(), 'sysverb_insert_and_stay');
        });
    });

    return false;
}
